/* The app's main texts in the 25 most used languages, as in the Android app (lib/i18n.dart): the
 * same table, kept the same by tvlite/tools/make_i18n.py. Keys are the English texts; anything not
 * in the table stays English. The table of the language in use is a file of its own (js/lang/xx.js),
 * which index.html loads before the screens, so English costs nothing.
 * Settings › Language: Automatic (the TV's language when the app has it) or one of the 25. */
var I18N = { rows: {} };

(function () {
  'use strict';

  /* <generated by tvlite/tools/make_i18n.py> */
  I18N.langs = [["en", "English", "English"], ["zh", "Chinese", "中文"], ["hi", "Hindi", "हिन्दी"], ["es", "Spanish", "Español"], ["fr", "French", "Français"], ["ar", "Arabic", "العربية"], ["bn", "Bengali", "বাংলা"], ["pt", "Portuguese", "Português"], ["ru", "Russian", "Русский"], ["ur", "Urdu", "اردو"], ["id", "Indonesian", "Bahasa Indonesia"], ["de", "German", "Deutsch"], ["ja", "Japanese", "日本語"], ["pa", "Punjabi", "ਪੰਜਾਬੀ"], ["tr", "Turkish", "Türkçe"], ["vi", "Vietnamese", "Tiếng Việt"], ["ko", "Korean", "한국어"], ["it", "Italian", "Italiano"], ["fa", "Persian", "فارسی"], ["ta", "Tamil", "தமிழ்"], ["te", "Telugu", "తెలుగు"], ["mr", "Marathi", "मराठी"], ["th", "Thai", "ไทย"], ["pl", "Polish", "Polski"], ["nl", "Dutch", "Nederlands"]];
  I18N.keys = ["Live TV", "Movies", "Series", "Catch Up", "Channels and TV guide", "Films on demand", "Seasons and episodes", "Replay past TV", "Playlists", "Settings", "Sign out", "Update", "My device", "Device ID", "Device Key", "VOD Player", "Live Player", "Parental Control", "Main Wallpaper", "Manage Categories", "Clear Cache", "Language", "Application Info", "Search", "Favourites", "Recent", "All Live Channels", "All Movies", "All Series", "Full screen", "TV Guide", "Favourite", "Press OK to watch here", "Loading the guide…", "No programme information for this channel.", "Audio language", "Subtitles", "Quality", "Back", "Channel list", "Clear cache now", "Automatic (TV language)", "Default", "Pause", "Play", "Continue Watching", "Who's watching?", "Kids", "In use", "Add profile", "Change profile", "Kids profile", "Kids categories", "Ask when the app starts", "Profiles", "Last channel", "Start Over", "No previous channel yet.", "Start Over works on channels with catch-up (recordings on the server).", "The TV guide of this channel is not loaded yet.", "The TV guide shows no programme on now.", "Help", "Report a problem", "Start with the last channel", "Something does not work? Send a report: the app's recent log and this TV's details go to the support team (no passwords).", "Recently Added", "Sort", "Default order", "Newest added", "A–Z", "Year (newest first)", "Rating (best first)", "Titles without that information go to the end.", "This playlist does not say when titles were added.", "A channel does not play", "Picture freezes or buffers", "No sound or wrong language", "A film or series does not play", "TV Guide is wrong or missing", "The app is slow or closes", "Something else", "A report was sent a moment ago. Please wait a minute.", "Choose what went wrong (or write a note).", "Could not send the report. Check the internet and try again.", "Report sent", "Thank you. Your report number is", "The support team can see what happened on this TV.", "Thank you.", "What went wrong? The app sends its recent log, this TV's model and the last channel or film to the support team. No password is sent.", "Note (optional), e.g. the channel name", "Cancel", "Send", "Voice", "Voice search", "Voice control", "Say the name", "Say a channel, film or series", "Where should I search?", "Say a channel name, \"next\" or \"start over\"", "Say \"pause\", \"next\" or \"back 30 seconds\"", "Live TV cannot go forward.", "A live channel cannot pause.", "There is no next episode.", "Nothing was heard. Try again.", "Not understood:", "Demo", "Exit demo", "Try the app first:", "Watch the demo", "Loading the demo…"];
  /* </generated by tvlite/tools/make_i18n.py> */

  var index = {};
  for (var i = 0; i < I18N.keys.length; i++) index[I18N.keys[i]] = i;
  I18N.add = function (code, row) { I18N.rows[code] = row; };

  /** The language chosen in Settings ('auto' = the TV's, or a code). English until one is chosen: the
   *  translations cover the main texts only, and the TV stores test the language the app is listed in. */
  App.uiLanguage = function () { var v = S.get('ui_lang', 'en'); return typeof v === 'string' && v ? v : 'en'; };
  /** The TV's own language (its first two letters). */
  App.tvLanguage = function () {
    var l = String(navigator.language || (navigator.languages && navigator.languages[0]) || 'en').toLowerCase();
    return l.substring(0, 2);
  };
  function known(code) {
    for (var k = 0; k < I18N.langs.length; k++) if (I18N.langs[k][0] === code) return true;
    return false;
  }
  /** The language in use: the choice, or the TV's language when the app has it, else English. */
  App.lang = function () {
    var c = App.uiLanguage();
    if (c === 'auto') c = App.tvLanguage();
    return known(c) ? c : 'en';
  };
  var lang = App.lang();

  /** The text in the app's language. key: the English text of the table; english: what English
   *  shows when the app's own English wording differs from the table's (e.g. "TV Series"). */
  App.t = function (key, english) {
    var row = I18N.rows[lang], i = index[key];
    if (!row || i == null || !row[i]) return english || key;
    return row[i];
  };
  /** Right-to-left languages (their texts keep the app's layout). */
  App.rtl = function () { return lang === 'ar' || lang === 'ur' || lang === 'fa'; };

  /** Settings › Language: the app starts again in the chosen language. */
  App.languageDialog = function () {
    var box = U.el('div', 'langgrid'), cur = App.uiLanguage(), first = null;
    var list = [['auto', App.t('Automatic (TV language)'), '']].concat(I18N.langs);
    list.forEach(function (l) {
      var on = l[0] === cur;
      var b = U.el('span', 'lg2 f' + (on ? ' sel' : ''), U.icon(on ? 'radioOn' : 'radioOff') + '<span class="own">' + U.esc(l[0] === 'auto' ? l[1] : l[2]) + '</span>' +
        (l[0] !== 'auto' && l[2] !== l[1] ? '<span class="en">' + U.esc(l[1]) + '</span>' : ''));
      b._ok = function () {
        if (l[0] === cur) { d.close(); return; }
        S.set('ui_lang', l[0]);
        App.log('language: ' + l[0]);
        Player.stop();
        location.reload();
      };
      box.appendChild(b);
      if (on) first = b;
    });
    var d = UI.dialog({ title: App.t('Language'), html: box, width: 1720, buttons: [{ label: App.t('Cancel'), pri: true }], focusEl: first });
  };
})();
